def encode(s):
    """Encode runs of letters as character followed by run length.

    A run length of 1 is omitted.
    """
    if not s:
        return ""

    result = []
    previous = s[0]
    count = 1

    for char in s[1:]:
        if char == previous:
            count += 1
        else:
            result.append(previous)
            if count > 1:
                result.append(str(count))
            previous = char
            count = 1

    result.append(previous)
    if count > 1:
        result.append(str(count))

    return "".join(result)


def decode(s):
    """Decode a string produced by encode, including multi-digit counts."""
    result = []
    i = 0
    n = len(s)

    while i < n:
        char = s[i]
        if not char.isalpha():
            raise ValueError("invalid encoded string")
        i += 1

        start = i
        while i < n and "0" <= s[i] <= "9":
            i += 1

        if start == i:
            count = 1
        else:
            count = int(s[start:i])

        result.append(char * count)

    return "".join(result)
